#!/usr/bin/env python3
"""Build the static portfolio using only Python's standard library."""
import json
from pathlib import Path
from html import escape

ROOT = Path(__file__).resolve().parent
OUT = ROOT / 'dist'
DATA = json.loads((ROOT / 'content.json').read_text())
PAGES = json.loads((ROOT / 'pages.json').read_text())
PERSON = DATA['person']
PROJECTS = DATA['projects']
e = lambda text: escape(str(text), quote=True)

def link(text, href, cls='text-link', external=False):
    return f'<a class="{cls}" href="{e(href)}"'+(' target="_blank" rel="noopener noreferrer"' if external else '')+f'>{text}<span class="arrow" aria-hidden="true">↗</span></a>'

def layout(title, body, active='', description=None):
    nav = ''.join(f'<a href="{slug}.html"'+(' aria-current="page"' if active == slug else '')+f'>{name}</a>' for slug,name in [('projects','Projects'),('about','About'),('resume','Resume'),('contact','Contact')])
    description = description or 'Mechanical engineering portfolio of Andrew Honer, a CU Boulder student working in CAD, reverse engineering, fabrication, and electronics.'
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#204d36"><title>{e(title)} | Andrew Honer</title><meta name="description" content="{e(description)}"><meta property="og:title" content="{e(title)} | Andrew Honer"><meta property="og:description" content="{e(description)}"><meta property="og:type" content="website"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="styles.css"><script src="site.js" defer></script></head>
<body><a class="skip" href="#main">Skip to content</a><header class="header"><div class="container header-inner"><a class="brand" href="index.html" aria-label="Andrew Honer, home"><span class="monogram" aria-hidden="true">AH</span><span class="wordmark">Andrew Honer</span></a><button class="menu-toggle" aria-expanded="false" aria-controls="main-nav" type="button">Menu</button><nav class="nav" id="main-nav" aria-label="Main navigation">{nav}</nav></div></header>
<main id="main">{body}</main><footer class="footer"><div class="container footer-inner"><span>Andrew Honer · Boulder, Colorado</span><div class="footer-links"><a href="mailto:{e(PERSON['email'])}">Email ↗</a><a href="{e(PERSON['linkedin'])}" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a><a href="assets/Andrew_Honer_Resume.pdf" download="Andrew_Honer_Resume.pdf">Resume ↓</a></div></div></footer>
<dialog class="lightbox" aria-label="Project image viewer"><div class="lightbox-top"><span class="lightbox-counter"></span><button type="button" class="icon-button" data-close aria-label="Close image viewer">Close ×</button></div><img class="lightbox-image" alt=""><div class="lightbox-bottom"><p class="lightbox-caption"></p><div class="lightbox-controls"><button class="icon-button" type="button" data-direction="-1" aria-label="Previous image">← Previous</button><button class="icon-button" type="button" data-direction="1" aria-label="Next image">Next →</button></div></div></dialog></body></html>'''

def write(slug, title, body, active='', description=None):
    (OUT/f'{slug}.html').write_text(layout(title,body,active,description))

def head(kicker, title, text='', subtitle=''):
    return f'<div class="page-head"><div class="eyebrow">{e(kicker)}</div><h1>{e(title)}</h1>'+ (f'<p class="subtitle">{e(subtitle)}</p>' if subtitle else '')+(f'<p class="deck">{e(text)}</p>' if text else '')+'</div>'

def card(p):
    visual = f'<div class="card-image {"cad" if p["slug"]=="nitecore" else ""}"><img src="assets/{e(p["hero"])}" alt="{e(p["hero_alt"])}" width="900" height="650" loading="lazy"><span class="image-index">{p["number"]}</span></div>' if p.get('hero') else f'<div class="ongoing-cover"><span class="status">Ongoing project</span><span class="cover-title">{e(p["title"])}</span><span class="cover-footer">{e(p["year"])}<span>Development in progress</span></span></div>'
    return f'<a class="project-card" href="{p["slug"]}.html" data-category="{e(p["category"])}">{visual}<div class="card-text"><div class="card-kicker">{e(p["category_label"])}</div><div class="card-title-line"><h3>{e(p["title"])}</h3><span class="arrow" aria-hidden="true">↗</span></div><p>{e(p["summary"])}</p></div></a>'

def figure(image, alt, caption, cls='', lazy=True):
    return f'<figure class="{cls}"><button class="figure-button" type="button" data-view="assets/{e(image)}" data-caption="{e(caption)}" data-alt="{e(alt)}" aria-label="Enlarge image: {e(alt)}"><img src="assets/{e(image)}" alt="{e(alt)}"'+(' loading="lazy"' if lazy else ' fetchpriority="high"')+f'></button><figcaption>{e(caption)}</figcaption></figure>'

def gallery(p):
    if not p.get('gallery'):return ''
    first=p['gallery'][0]
    thumbs=''.join(f'<button class="thumb" type="button" aria-pressed="{str(i==0).lower()}" aria-label="View image {i+1}: {e(x["alt"])}"><img src="assets/{e(x["image"])}" alt="" loading="lazy"></button>' for i,x in enumerate(p['gallery']))
    return f'<section class="gallery-section" aria-labelledby="gallery-title"><div class="eyebrow">Project gallery</div><h2 id="gallery-title">{e(p["gallery_title"])}</h2><div data-gallery="{e(json.dumps(p["gallery"]))}"><figure><button class="figure-button" type="button" data-view="assets/{e(first["image"])}" data-caption="{e(first["caption"])}" data-alt="{e(first["alt"])}" aria-label="Enlarge image: {e(first["alt"])}"><img class="gallery-main" src="assets/{e(first["image"])}" alt="{e(first["alt"])}" loading="lazy"></button><figcaption class="gallery-caption"><span class="gallery-description">{e(first["caption"])}</span><span class="gallery-count" aria-live="polite">1 / {len(p["gallery"])}</span></figcaption></figure><div class="thumbs" aria-label="Choose a gallery image">{thumbs}</div></div></section>'

def project_page(p, next_p):
    facts='<dl class="facts">'+''.join(f'<div class="fact"><dt>{e(k)}</dt><dd>{e(v)}</dd></div>' for k,v in p['facts'])+'</dl>'
    hero=figure(p['hero'],p['hero_alt'],p['hero_caption'],'case-hero'+(' photo' if p['slug']=='eagle-scout' else ''),False) if p.get('hero') else f'<div class="placeholder"><div class="placeholder-label">Work in progress</div><p>{e(p["placeholder"])}</p></div>'
    toc='<nav class="case-nav" aria-label="On this page"><span class="eyebrow">On this page</span>'+''.join(f'<a href="#{e(s["id"])}">{e(s["title"])}</a>' for s in p['sections'])+'</nav>'
    sections=''
    for s in p['sections']:
        sections+=f'<section class="case-section" id="{e(s["id"])}"><div class="eyebrow">{e(s["label"])}</div><h2>{e(s["title"])}</h2>'+''.join(f'<p>{e(t)}</p>' for t in s['paragraphs'])
        if s.get('image'):sections+=figure(s['image'],s['alt'],s['caption'])
        if s.get('pair'):sections+='<div class="figure-pair'+(' photo-pair' if p['slug']=='eagle-scout' else '')+'">'+''.join(figure(i['image'],i['alt'],i['caption']) for i in s['pair'])+'</div>'
        sections+='</section>'
    body='<div class="container"><div class="breadcrumb"><a href="projects.html">All projects</a> <span aria-hidden="true">/</span> '+e(p['title'])+'</div>'+head(p['category_label']+' / '+p['year'],p['title'],p['lead'],p['subtitle'])+facts+hero
    if p.get('note'):body+=f'<p class="project-note">{e(p["note"])}</p>'
    body+=f'<div class="case-layout">{toc}<div>{sections}</div></div>'+gallery(p)
    if p['status']=='Ongoing':body+='<div style="height:35px"></div>'
    body+=f'<a class="next-project" href="{next_p["slug"]}.html"><div><span class="eyebrow">Next project</span><h3>{e(next_p["title"])}</h3></div><span class="arrow" aria-hidden="true">↗</span></a></div>'
    write(p['slug'],p['title'],body,'projects',p['summary'])

def build():
    OUT.mkdir(exist_ok=True)
    ongoing=''.join(f'<a class="ongoing-row" href="{p["slug"]}.html"><span class="number">{p["number"]}</span><div><h3>{e(p["title"])}</h3><p>{e(p["subtitle"])}</p></div><div class="ongoing-right"><span class="status">Ongoing</span><span class="arrow" aria-hidden="true">↗</span></div></a>' for p in PROJECTS[2:])
    home=f'''<section class="hero container"><div class="eyebrow">Mechanical engineering / CU Boulder</div><h1>Andrew Honer</h1><p class="intro">{e(PERSON['intro'])}</p><div class="inline-links"><a class="text-link" href="#selected-work">Explore my work <span class="arrow" aria-hidden="true">↓</span></a>{link('A little about me','about.html')}</div></section><section class="work-section container" id="selected-work" aria-labelledby="selected-title"><div class="section-head"><h2 id="selected-title">Selected work</h2><span>CAD, construction & the process behind them</span></div><div class="featured-grid">{''.join(card(p) for p in PROJECTS[:2])}</div></section><section class="ongoing container" aria-labelledby="ongoing-title"><div class="section-head"><h2 id="ongoing-title">Currently working on</h2><span>2026 / In progress</span></div><div class="ongoing-list">{ongoing}</div></section><section class="about-band"><div class="container about-band-inner"><div><div class="eyebrow">{e(PAGES["home"]["about_kicker"])}</div><h2>{e(PAGES["home"]["about_title"])}</h2></div><div><p>{e(PAGES["home"]["about_text"])}</p>{link('More about my background','about.html')}</div></div></section>'''
    write('index','Engineering portfolio',home)
    filters=''.join(f'<button class="filter" type="button" data-filter="{key}" aria-pressed="{str(key=="all").lower()}">{name}</button>' for key,name in [('all','All work'),('cad','CAD & design'),('leadership','Construction & leadership'),('electronics','Electronics')])
    write('projects','Projects',f'<div class="container page-content">'+head('The work','Projects','Completed projects and ongoing work in mechanical design, construction, and electronics.')+f'<div class="filters" aria-label="Filter projects">{filters}</div><p class="filter-result" aria-live="polite">4 projects</p><div class="project-grid">'+''.join(card(p) for p in PROJECTS)+'</div></div>','projects')
    about=f'''<div class="container page-content">{head('Background & interests',PAGES['about']['title'],PAGES['about']['deck'])}<div class="about-layout"><div class="about-copy"><h2>{e(PAGES["about"]["heading"])}</h2>{''.join('<p>'+e(t)+'</p>' for t in PAGES['about']['paragraphs'])}</div><div>{figure(PAGES['about']['photo'],PAGES['about']['photo_alt'],PAGES['about']['photo_caption'],'about-photo',False)}</div></div><div class="about-details"><section><h3>Education & certification</h3><div class="detail-title">University of Colorado Boulder</div><p class="detail-body">B.S. Mechanical Engineering<br>Minor in Physics · Expected May 2029<br>Dean’s List, Fall 2025 & Spring 2026</p><div class="detail-title" style="margin-top:22px">Certified SOLIDWORKS Associate</div><p class="detail-body">CSWA · Mechanical design</p></section><section><h3>Tools & hands-on experience</h3><ul class="skill-list"><li>SOLIDWORKS</li><li>Onshape</li><li>Engineering drawings</li><li>3D printing</li><li>Laser cutting</li><li>Fabrication</li><li>Power tools</li><li>C++</li><li>Java</li><li>Excel</li></ul><h3 style="margin-top:24px">{e(PAGES["about"]["experience_heading"])}</h3><p class="detail-body">{e(PAGES["about"]["experience_text"])}</p></section></div><section class="opportunity"><div class="eyebrow">What’s next</div><h2 style="font-size:30px;margin:12px 0 18px">{e(PAGES["about"]["opportunity_heading"])}</h2><p>{e(PAGES["about"]["opportunity_text"])}</p>{link('Get in touch','contact.html')}</section></div>'''
    write('about','About',about,'about')
    resume=f'''<div class="container page-content">{head('Experience & qualifications','Resume','Education, technical experience, and work with teams.')}<div class="resume-top"><p class="small muted">View the highlights below or download my resume.</p><a class="button" href="assets/Andrew_Honer_Resume.pdf" download="Andrew_Honer_Resume.pdf">Download resume PDF <span aria-hidden="true">↓</span></a></div><section class="resume-section"><h2>Education</h2><div class="resume-item"><h3>University of Colorado Boulder</h3><div class="meta">B.S. Mechanical Engineering · Minor in Physics · Expected May 2029</div><p>GPA: 3.96<br>Dean’s List: Fall 2025 and Spring 2026.</p><p>Coursework includes SOLIDWORKS and Fabrication, C++, Modern Physics, and Calculus III.</p></div></section><section class="resume-section"><h2>Engineering projects</h2><div><div class="resume-item"><h3><a href="nitecore.html">Nitecore NWL20 reverse engineering ↗</a></h3><div class="meta">MCEN 1025 · April–May 2026</div><p>Disassembled and measured the work light, then created a 16-part SOLIDWORKS assembly with two subassemblies and five engineering drawings.</p></div><div class="resume-item"><h3><a href="eagle-scout.html">Eagle Scout service project ↗</a></h3><div class="meta">Animal Assisted Happiness · 2024</div><p>Planned, budgeted, and led a shed and accessible-sink build, coordinating volunteers contributing about 229 total work hours.</p></div><div class="resume-item"><h3><a href="autonomous-racing.html">CU Autonomous Racing ↗</a></h3><div class="meta">Ongoing</div><p>Steering-system design and master CAD assembly work.</p></div></div></section><section class="resume-section"><h2>Work & leadership</h2><div><div class="resume-item"><h3>Camp Galileo</h3><div class="meta">Lead Instructor · Palo Alto, CA · June–July 2026</div><p>Led groups of 20 campers ages 10–12 through STEM projects, including go-karts and escape rooms. Taught nine counselors in training leadership and instructional skills, and helped campers troubleshoot their designs.</p></div><div class="resume-item"><h3>Target</h3><div class="meta">Guest Advocate · Mountain View, CA · May–August 2026</div><p>Checked out guests, answered questions, organized product displays, and supported daily guest-service tasks.</p></div><div class="resume-item"><h3>Scouts BSA, Troop 31</h3><div class="meta">Multiple leadership positions · Los Altos, CA · 2018–2025</div><p>Eagle Scout with four Palms and 41 merit badges. Served as Senior Patrol Leader and Assistant Senior Patrol Leader, organized meetings and outings, and mentored younger Scouts.</p></div><div class="resume-item"><h3>KMVT 15 Silicon Valley Media</h3><div class="meta">Summer Intern · June–July 2024</div><p>Supported a media camp, supervised students, operated studio equipment, and helped set up and take down the studio.</p></div></div></section><section class="resume-section"><h2>Skills & certification</h2><div class="resume-item"><h3>Certified SOLIDWORKS Associate (CSWA)</h3><p style="margin-top:12px">SOLIDWORKS, Onshape, engineering drawings, fabrication, 3D printing, laser cutting, power tools, C++, Java, and Excel.</p></div></section></div>'''
    write('resume','Resume',resume,'resume')
    contact=f'''<div class="container page-content">{head('Let’s connect','Contact','I’m interested in mechanical engineering internships and opportunities to learn through hands-on work.')}<div class="contact-layout"><div><div class="eyebrow">Boulder, Colorado</div><h2 style="margin-top:15px">{e(PAGES["contact"]["heading"])}</h2><p>{e(PAGES["contact"]["text"])}</p><div class="contact-actions"><a class="button" href="mailto:{e(PERSON['email'])}">Write an email <span aria-hidden="true">↗</span></a><button class="button secondary" type="button" data-copy-email="{e(PERSON['email'])}">Copy email</button></div><div class="copy-status" role="status"></div></div><div><a class="contact-link" href="mailto:{e(PERSON['email'])}"><span class="eyebrow">Email</span><span class="contact-value">{e(PERSON['email'])}<span aria-hidden="true">↗</span></span></a><a class="contact-link" href="{e(PERSON['linkedin'])}" target="_blank" rel="noopener noreferrer"><span class="eyebrow">LinkedIn</span><span class="contact-value">linkedin.com/in/andrew-honer<span aria-hidden="true">↗</span></span></a><a class="contact-link" href="assets/Andrew_Honer_Resume.pdf" download="Andrew_Honer_Resume.pdf"><span class="eyebrow">Resume</span><span class="contact-value">Download PDF<span aria-hidden="true">↓</span></span></a></div></div></div>'''
    write('contact','Contact',contact,'contact')
    for i,p in enumerate(PROJECTS):project_page(p,PROJECTS[(i+1)%len(PROJECTS)])
    print(f'Built {len(list(OUT.glob("*.html")))} pages in {OUT}')

if __name__=='__main__':build()
